cssRules:
.kbd-grid {
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: #101216;
  border: 1px solid #20242c;
  border-radius: 8px;
  padding: 16px;
}
.kbd-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  color: #c0c6d4;
}
.kbd-row kbd {
  font-family: ui-monospace, monospace;
  font-size: 11px;
  padding: 2px 6px;
  background: #1c202a;
  border: 1px solid #333a4d;
  border-bottom: 2px solid #262c3b;
  border-radius: 4px;
  color: #ffffff;
}
